import type { components } from './generated/schema';
import { createControlClient } from './client';
import { ControlRequestError } from './transport';
import { newIntentKey } from './resources';
export { parseDollarCents, formatCents } from './currency';

// These are the existing mounted local Control projections. Their paths are
// deliberately distinct from unimplemented /grants endpoints.
// OpenAPI declares the mounted contracts; generated types are regenerated by
// `make webui-generate` in the qualified release environment.
export type ServiceGrant = 'models' | 'mcp' | 'search';
export type ServiceRequestLimit = { service: ServiceGrant; requests_per_minute: number }; 
export type Permission = { workspace: string; action: 'use'; expires_at?: string; services?: ServiceGrant[]; request_limits?: ServiceRequestLimit[] };
export type Principal = { id: string; label: string; kind: string; status: string; revision: string; created_at?: string; permissions: Permission[] };
export type Credential = { id: string; workspace: string; created_at: string };
export type IssueCredential = { credential: Credential; token?: string; secret_not_recoverable?: boolean };
export type PermissionReview = { principal: string; workspace: string; operation: string; revision: string;
  before: Permission | null; after: Permission | null; affected_credentials: number; approval_class: string; warning: string };
export type PermissionResult = { principal: string; workspace: string; revision: string; permission: Permission | null; allowed: boolean; replayed: boolean };
export type CredentialReview = { principal: string; credential: Credential; revision: string; approval_class: string; warning: string };
export type CredentialResult = { principal: Principal; credential: string; revoked: boolean; replayed: boolean };
export type Publication = components['schemas']['WorkspacePublication'];
export type RemoteAddress = components['schemas']['RemoteAddress'];
export type Limit = { currency: 'USD'; amount_cents: number; window: 'day' | 'month';
  mode: 'stop_new_billable_work' | 'observe_only'; unknown_price: 'reject' };
export type LimitStatus = { workspace: string; limit: Limit | null; window_key: string; window_start: string; window_end: string;
  currency: string; reserved_cents: string; settled_cents: string; uncertain_cents: string; charged_cents: string;
  remaining_cents: string | null; unknown_price_operations: number; partial_quantity_operations: number; unquoted_operations: number };
export type LimitSnapshot = { status: LimitStatus; revision: string };
export type LimitApproval = { id: string; workspace: string; operation: string; digest: string; revision: string; expires_at: string; used: boolean };

const api = createControlClient();
function required<T>(data: T | undefined): T {
  if (data === undefined) throw new Error('Node returned no resource.');
  return data;
}
const etag = (revision: string) => `"${revision}"`;
const pathParams = (fields: Record<string, string>) => ({ path: fields });

export async function listPrincipals(): Promise<Principal[]> {
  return required((await api.GET('/api/v1/principals')).data as Principal[] | undefined);
}
export async function getPrincipal(id: string): Promise<Principal> {
  return required((await api.GET('/api/v1/principals/{id}', { params: pathParams({ id }) } as never)).data as Principal | undefined);
}
export async function createPrincipal(label: string, key: string): Promise<Principal> {
  return required((await api.POST('/api/v1/principals', { params: { header: { 'Idempotency-Key': key } }, body: { label } } as never)).data as Principal | undefined);
}
export async function renamePrincipal(principal: Principal, label: string): Promise<Principal> {
  return required((await api.PATCH('/api/v1/principals/{id}', { params: { ...pathParams({ id: principal.id }), header: { 'If-Match': etag(principal.revision) } }, body: { label } } as never)).data as Principal | undefined);
}
export async function listCredentials(id: string): Promise<Credential[]> {
  return required((await api.GET('/api/v1/principals/{id}/credentials' as never, { params: pathParams({ id }) } as never)).data as Credential[] | undefined);
}
export async function issueCredential(id: string, workspace: string, key: string): Promise<IssueCredential> {
  return required((await api.POST('/api/v1/principals/{id}/credentials' as never, { params: { ...pathParams({ id }), header: { 'Idempotency-Key': key } }, body: { workspace } } as never)).data as IssueCredential | undefined);
}
export async function previewPermission(workspace: string, id: string, grant: boolean, expiresAt?: string, services?: ServiceGrant[], requestLimits?: ServiceRequestLimit[]): Promise<PermissionReview> {
  const params = { ...pathParams({ slug: workspace, id }), query: { dry_run: true } };
  const result = grant ? await api.PUT('/api/v1/workspaces/{slug}/permissions/{id}' as never,
    { params, body: { action: 'use', ...(expiresAt ? { expires_at: expiresAt } : {}), ...(services ? { services } : {}), ...(requestLimits !== undefined ? { request_limits: requestLimits } : {}) } } as never) :
    await api.DELETE('/api/v1/workspaces/{slug}/permissions/{id}' as never, { params, body: {} } as never);
  return required(result.data as PermissionReview | undefined);
}
export async function applyPermission(review: PermissionReview, key: string): Promise<PermissionResult> {
  const params = { ...pathParams({ slug: review.workspace, id: review.principal }),
    header: { 'If-Match': etag(review.revision), 'Idempotency-Key': key } };
  const result = review.operation === 'grant' ? await api.PUT('/api/v1/workspaces/{slug}/permissions/{id}' as never,
    { params, body: { action: 'use', ...(review.after?.expires_at ? { expires_at: review.after.expires_at } : {}), ...(review.after?.services ? { services: review.after.services } : {}), request_limits: review.after?.request_limits ?? [] } } as never) :
    await api.DELETE('/api/v1/workspaces/{slug}/permissions/{id}' as never, { params, body: {} } as never);
  return required(result.data as PermissionResult | undefined);
}
export async function previewCredentialRevocation(id: string, credential: string): Promise<CredentialReview> {
  return required((await api.DELETE('/api/v1/principals/{id}/credentials/{credential}' as never,
    { params: { ...pathParams({ id, credential }), query: { dry_run: true } }, body: {} } as never)).data as CredentialReview | undefined);
}
export async function applyCredentialRevocation(review: CredentialReview, key: string): Promise<CredentialResult> {
  return required((await api.DELETE('/api/v1/principals/{id}/credentials/{credential}' as never,
    { params: { ...pathParams({ id: review.principal, credential: review.credential.id }), header: { 'If-Match': etag(review.revision), 'Idempotency-Key': key } }, body: {} } as never)).data as CredentialResult | undefined);
}
export async function readLimitStatus(slug: string): Promise<LimitSnapshot> {
  const result = await api.GET('/api/v1/workspaces/{slug}/limits/status' as never, { params: pathParams({ slug }) } as never);
  const revision = result.response.headers.get('ETag');
  if (!revision || !/^"[0-9a-f]{64}"$/.test(revision)) throw new Error('Node did not supply a strong accounting revision.');
  return { status: required(result.data as LimitStatus | undefined), revision: revision.slice(1, -1) };
}
export async function previewLimit(slug: string, limit: Limit): Promise<LimitApproval> {
  return required((await api.POST('/api/v1/workspaces/{slug}/limits/preview' as never,
    { params: pathParams({ slug }), body: limit } as never)).data as LimitApproval | undefined);
}
export async function applyLimit(approval: LimitApproval, limit: Limit): Promise<Limit> {
  return required((await api.POST('/api/v1/workspaces/{slug}/limits/apply' as never,
    { params: pathParams({ slug: approval.workspace }), body: { approval_id: approval.id, limit } } as never)).data as Limit | undefined);
}
export async function clearLimit(slug: string, revision: string): Promise<void> {
  await api.DELETE('/api/v1/workspaces/{slug}/limits' as never, { params: { ...pathParams({ slug }), header: { 'If-Match': etag(revision) } } } as never);
}
// Publication is a Workspace reachability bit; its revision protects ordering of
// administrative changes, not an independent credential or protocol allowlist.
export async function readPublication(slug: string): Promise<Publication> {
  return required((await api.GET('/api/v1/workspaces/{slug}/publications',
    { params: { path: { slug } } })).data as Publication | undefined);
}
export async function setPublication(current: Publication, published: boolean): Promise<Publication> {
  const params = { path: { slug: current.workspace, remote_address_id: 'relay' as const },
    header: { 'If-Match': etag(current.revision) } };
  const response = published ? await api.PUT('/api/v1/workspaces/{slug}/publications/{remote_address_id}',
    { params }) : await api.DELETE('/api/v1/workspaces/{slug}/publications/{remote_address_id}',
    { params });
  return required(response.data as Publication | undefined);
}
export async function listRemoteAddresses(): Promise<RemoteAddress[]> {
  return required((await api.GET('/api/v1/remote-addresses')).data as RemoteAddress[] | undefined);
}

export { ControlRequestError, newIntentKey };
